1	use std::env;
2	use std::fs;
3	use std::process::ExitCode;
4	
5	const VERSION: &str = "0.1.0";
6	
7	const USAGE: &str = "\
8	Usage:
9	    roottrace root <file>
10	    roottrace prove <file> <record-index>
11	    roottrace --version
12	
13	Commands:
14	    root <file>
15	        Print the SHA-256 RFC 6962 Merkle Tree Hash of all records in <file>
16	        as one line of 64 lowercase hexadecimal characters.
17	
18	    prove <file> <record-index>
19	        Print the RFC 6962 section 2.1.1 inclusion (membership) proof for the
20	        record at <record-index> within the whole batch. The index is
21	        0-based and counts records in file order: 0 is the first record,
22	        1 the second, and so on; the same content at multiple positions gets
23	        the proof for the exact position given, with no deduplication. Output
24	        is one JSON object with the fields tree_size, leaf_index, root and
25	        audit_path (leaf-to-root hashes, lowercase hex; empty for a batch of
26	        exactly one record).
27	
28	        Example:
29	            roottrace prove batch.txt 0
30	
31	Exit status:
32	    0  success
33	    1  the file cannot be read, or the record index does not exist
34	    2  usage error (unknown command, missing or extra arguments, bad index)";
35	
36	fn main() -> ExitCode {
37	    let args: Vec<String> = env::args().skip(1).collect();
38	    match args.as_slice() {
39	        [flag] if flag == "--version" => {
40	            println!("roottrace {VERSION}");
41	            ExitCode::SUCCESS
42	        }
43	        [cmd, path] if cmd == "root" => match merkle_root_of_file(path) {
44	            Ok(root) => {
45	                println!("{}", hex(&root));
46	                ExitCode::SUCCESS
47	            }
48	            Err(reason) => {
49	                eprintln!("roottrace: {reason}");
50	                ExitCode::FAILURE
51	            }
52	        },
53	        [cmd, path, index] if cmd == "prove" => match parse_index(index) {
54	            Some(index) => match proof_for_file(path, index) {
55	                Ok(proof) => {
56	                    println!("{}", proof);
57	                    ExitCode::SUCCESS
58	                }
59	                Err(ProveError::Read(reason)) => {
60	                    eprintln!("roottrace: {reason}");
61	                    ExitCode::FAILURE
62	                }
63	                Err(ProveError::Missing(index, size)) => {
64	                    if size == 0 {
65	                        eprintln!(
66	                            "roottrace: record index {index} does not exist: the file holds zero records"
67	                        );
68	                    } else {
69	                        eprintln!(
70	                            "roottrace: record index {index} does not exist: file holds {size} record(s), valid indices are 0 through {}",
71	                            size - 1
72	                        );
73	                    }
74	                    ExitCode::FAILURE
75	                }
76	            },
77	            None => {
78	                eprintln!("roottrace: invalid record index '{index}': expected a decimal non-negative integer of ASCII digits");
79	                eprintln!("{USAGE}");
80	                ExitCode::from(2)
81	            }
82	        },
83	        _ => {
84	            eprintln!("{USAGE}");
85	            ExitCode::from(2)
86	        }
87	    }
88	}
89	
90	enum ProveError {
91	    Read(String),
92	    Missing(u64, u64),
93	}
94	
95	fn merkle_root_of_file(path: &str) -> Result<[u8; 32], String> {
96	    let data = fs::read(path).map_err(|e| format!("cannot read '{path}': {e}"))?;
97	    Ok(mth(&split_records(&data)))
98	}
99	
100	fn proof_for_file(path: &str, index: u64) -> Result<String, ProveError> {
101	    let data = fs::read(path).map_err(|e| ProveError::Read(format!("cannot read '{path}': {e}")))?;
102	    let records = split_records(&data);
103	    let size = records.len() as u64;
104	    if index >= size {
105	        return Err(ProveError::Missing(index, size));
106	    }
107	    let idx = index as usize;
108	    let root = mth(&records);
109	    let audit_path = inclusion_path(&records, idx);
110	    Ok(proof_json(size, index, &root, &audit_path))
111	}
112	
113	/// Parse a record index: one or more ASCII decimal digits, non-negative, no
114	/// sign or whitespace, fitting in an unsigned 64-bit integer. Anything else
115	/// (including "+1", " 1", "1.0", "", "-1") is rejected.
116	fn parse_index(text: &str) -> Option<u64> {
117	    if text.is_empty() || !text.bytes().all(|b| b.is_ascii_digit()) {
118	        return None;
119	    }
120	    let mut value: u64 = 0;
121	    for b in text.bytes() {
122	        value = value.checked_mul(10)?.checked_add(u64::from(b - b'0'))?;
123	    }
124	    Some(value)
125	}
126	
127	/// Build the one-line JSON object printed by `prove`: integer tree_size and
128	/// leaf_index, the lowercase-hex root, and the audit path as a JSON array of
129	/// lowercase-hex hashes ordered leaf to root.
130	fn proof_json(tree_size: u64, leaf_index: u64, root: &[u8; 32], audit_path: &[[u8; 32]]) -> String {
131	    let mut out = String::new();
132	    out.push_str("{\"tree_size\":");
133	    out.push_str(&tree_size.to_string());
134	    out.push_str(",\"leaf_index\":");
135	    out.push_str(&leaf_index.to_string());
136	    out.push_str(",\"root\":\"");
137	    out.push_str(&hex(root));
138	    out.push_str("\",\"audit_path\":[");
139	    for (i, node) in audit_path.iter().enumerate() {
140	        if i > 0 {
141	            out.push(',');
142	        }
143	        out.push('"');
144	        out.push_str(&hex(node));
145	        out.push('"');
146	    }
147	    out.push_str("]}");
148	    out
149	}
150	
151	/// Split raw bytes into records on LF (0x0a). The separator is not part of
152	/// any record. A trailing LF terminates the last record without adding an
153	/// empty one; an empty file yields zero records.
154	fn split_records(data: &[u8]) -> Vec<&[u8]> {
155	    if data.is_empty() {
156	        return Vec::new();
157	    }
158	    let mut records: Vec<&[u8]> = data.split(|&b| b == b'\n').collect();
159	    if data.last() == Some(&b'\n') {
160	        records.pop();
161	    }
162	    records
163	}
