165	/// RFC 6962 section 2.1 Merkle Tree Hash over SHA-256.
166	fn mth(leaves: &[&[u8]]) -> [u8; 32] {
167	    match leaves.len() {
168	        0 => sha256(&[]),
169	        1 => {
170	            let mut input = Vec::with_capacity(1 + leaves[0].len());
171	            input.push(0x00);
172	            input.extend_from_slice(leaves[0]);
173	            sha256(&input)
174	        }
175	        n => {
176	            // Largest power of two strictly smaller than n.
177	            let k = 1usize << (usize::BITS - 1 - (n - 1).leading_zeros());
178	            let left = mth(&leaves[..k]);
179	            let right = mth(&leaves[k..]);
180	            let mut input = Vec::with_capacity(65);
181	            input.push(0x01);
182	            input.extend_from_slice(&left);
183	            input.extend_from_slice(&right);
184	            sha256(&input)
185	        }
186	    }
187	}
188	
189	/// RFC 6962 section 2.1.1 Merkle Audit Path for the record at `m` within a
190	/// batch of `n` records, ordered from the leaf level up to the root.
191	///
192	/// ```text
193	/// PATH(m, [d0]) = []
194	/// PATH(m, [d0..d(n-1)]) = PATH(m, [d0..d(k-1)]) + MTH([dk..d(n-1)])   if m < k
195	///                       = PATH(m, [dk..d(n-1)]) + MTH([d0..d(k-1)])   if m >= k
196	/// ```
197	///
198	/// with k the largest power of two strictly smaller than n. Uneven batches
199	/// are handled by the recursion itself: no leaf is duplicated and no empty
200	/// record is appended to round the size up to a power of two.
201	fn inclusion_path(leaves: &[&[u8]], m: usize) -> Vec<[u8; 32]> {
202	    let n = leaves.len();
203	    assert!(m < n, "leaf index {m} out of range for {n} record(s)");
204	    let mut path = Vec::new();
205	    inclusion_path_rec(leaves, m, &mut path);
206	    path
207	}
208	
209	fn inclusion_path_rec(leaves: &[&[u8]], m: usize, path: &mut Vec<[u8; 32]>) {
210	    let n = leaves.len();
211	    if n == 1 {
212	        return;
213	    }
214	    // Largest power of two strictly smaller than n.
215	    let k = 1usize << (usize::BITS - 1 - (n - 1).leading_zeros());
216	    if m < k {
217	        inclusion_path_rec(&leaves[..k], m, path);
218	        path.push(mth(&leaves[k..]));
219	    } else {
220	        inclusion_path_rec(&leaves[k..], m - k, path);
221	        path.push(mth(&leaves[..k]));
222	    }
223	}
