225	fn hex(digest: &[u8; 32]) -> String {
226	    let mut s = String::with_capacity(64);
227	    for b in digest {
228	        s.push(char::from_digit((b >> 4) as u32, 16).unwrap());
229	        s.push(char::from_digit((b & 0x0f) as u32, 16).unwrap());
230	    }
231	    s
232	}
