247	fn sha256(data: &[u8]) -> [u8; 32] {
248	    let mut h: [u32; 8] = [
249	        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab,
250	        0x5be0cd19,
251	    ];
252	
253	    let bit_len = (data.len() as u64).wrapping_mul(8);
254	    let mut msg = data.to_vec();
255	    msg.push(0x80);
256	    while msg.len() % 64 != 56 {
257	        msg.push(0);
258	    }
259	    msg.extend_from_slice(&bit_len.to_be_bytes());
260	
261	    for block in msg.chunks_exact(64) {
262	        let mut w = [0u32; 64];
263	        for (i, word) in block.chunks_exact(4).enumerate() {
264	            w[i] = u32::from_be_bytes([word[0], word[1], word[2], word[3]]);
265	        }
266	        for i in 16..64 {
267	            let s0 = w[i - 15].rotate_right(7) ^ w[i - 15].rotate_right(18) ^ (w[i - 15] >> 3);
268	            let s1 = w[i - 2].rotate_right(17) ^ w[i - 2].rotate_right(19) ^ (w[i - 2] >> 10);
269	            w[i] = w[i - 16]
270	                .wrapping_add(s0)
271	                .wrapping_add(w[i - 7])
272	                .wrapping_add(s1);
273	        }
274	
275	        let [mut a, mut b, mut c, mut d, mut e, mut f, mut g, mut hh] = h;
276	        for i in 0..64 {
277	            let s1 = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
278	            let ch = (e & f) ^ ((!e) & g);
279	            let t1 = hh
280	                .wrapping_add(s1)
281	                .wrapping_add(ch)
282	                .wrapping_add(K[i])
283	                .wrapping_add(w[i]);
284	            let s0 = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
285	            let maj = (a & b) ^ (a & c) ^ (b & c);
286	            let t2 = s0.wrapping_add(maj);
287	            hh = g;
288	            g = f;
289	            f = e;
290	            e = d.wrapping_add(t1);
291	            d = c;
292	            c = b;
293	            b = a;
294	            a = t1.wrapping_add(t2);
295	        }
296	
297	        h[0] = h[0].wrapping_add(a);
298	        h[1] = h[1].wrapping_add(b);
299	        h[2] = h[2].wrapping_add(c);
300	        h[3] = h[3].wrapping_add(d);
301	        h[4] = h[4].wrapping_add(e);
302	        h[5] = h[5].wrapping_add(f);
303	        h[6] = h[6].wrapping_add(g);
304	        h[7] = h[7].wrapping_add(hh);
305	    }
306	
307	    let mut out = [0u8; 32];
308	    for (i, word) in h.iter().enumerate() {
309	        out[i * 4..i * 4 + 4].copy_from_slice(&word.to_be_bytes());
310	    }
311	    out
312	}
