314	#[cfg(test)]
315	mod tests {
316	    use super::*;
317	
318	    fn hex_of(d: &[u8; 32]) -> String {
319	        hex(d)
320	    }
321	
322	    /// Leaf hash: SHA-256(0x00 || data).
323	    fn leaf_hash(data: &[u8]) -> [u8; 32] {
324	        let mut input = vec![0x00];
325	        input.extend_from_slice(data);
326	        sha256(&input)
327	    }
328	
329	    fn node_hash(left: &[u8; 32], right: &[u8; 32]) -> [u8; 32] {
330	        let mut input = Vec::with_capacity(65);
331	        input.push(0x01);
332	        input.extend_from_slice(left);
333	        input.extend_from_slice(right);
334	        sha256(&input)
335	    }
336	
337	    /// Verify an RFC 6962 inclusion proof with the RFC's recursive verifier:
338	    /// it re-derives the combination order from the tree geometry (k =
339	    /// largest power of two below the current subtree size) while consuming
340	    /// exactly the supplied sibling hashes. A wrong length, order or hash
341	    /// fails; the root computed here must equal the tree root.
342	    fn verify_proof(leaf: &[u8], m: usize, n: usize, path: &[[u8; 32]]) -> [u8; 32] {
343	        assert!(m < n);
344	        fn sub(leaf: &[u8], m: usize, n: usize, path: &[[u8; 32]], pos: &mut usize) -> [u8; 32] {
345	            if n == 1 {
346	                return leaf_hash(leaf);
347	            }
348	            let k = 1usize << (usize::BITS - 1 - (n - 1).leading_zeros());
349	            if m < k {
350	                let left = sub(leaf, m, k, path, pos);
351	                assert!(*pos < path.len(), "proof too short");
352	                let right = path[*pos];
353	                *pos += 1;
354	                node_hash(&left, &right)
355	            } else {
356	                let right = sub(leaf, m - k, n - k, path, pos);
357	                assert!(*pos < path.len(), "proof too short");
358	                let left = path[*pos];
359	                *pos += 1;
360	                node_hash(&left, &right)
361	            }
362	        }
363	        let mut pos = 0;
364	        let root = sub(leaf, m, n, path, &mut pos);
365	        assert_eq!(pos, path.len(), "proof too long: {pos} consumed of {}", path.len());
366	        root
367	    }
