369	    #[test]
370	    fn sha256_known_vectors() {
371	        assert_eq!(
372	            hex_of(&sha256(b"")),
373	            "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"
374	        );
375	        assert_eq!(
376	            hex_of(&sha256(b"abc")),
377	            "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"
378	        );
379	        // Longer than one block.
380	        assert_eq!(
381	            hex_of(&sha256(
382	                b"abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq"
383	            )),
384	            "248d6a61d20638b8e5c026930c3e6039a33ce45964ff2167f6ecedd419db06c1"
385	        );
386	    }
