388	    #[test]
389	    fn record_splitting() {
390	        assert_eq!(split_records(b""), Vec::<&[u8]>::new());
391	        assert_eq!(split_records(b"\n"), vec![b"".as_slice()]);
392	        assert_eq!(split_records(b"a\nb"), vec![b"a".as_slice(), b"b".as_slice()]);
393	        assert_eq!(split_records(b"a\nb\n"), vec![b"a".as_slice(), b"b".as_slice()]);
394	        assert_eq!(split_records(b"a\n\n"), vec![b"a".as_slice(), b"".as_slice()]);
395	        assert_eq!(split_records(b"a\n\n\n"), vec![b"a".as_slice(), b"".as_slice(), b"".as_slice()]);
396	        // CR is content, not a separator.
397	        assert_eq!(split_records(b"a\r\nb\r\n"), vec![b"a\r".as_slice(), b"b\r".as_slice()]);
398	        // Non-UTF-8 bytes are fine.
399	        assert_eq!(split_records(b"\xff\xfe\n\x00"), vec![b"\xff\xfe".as_slice(), b"\x00".as_slice()]);
400	    }
