402	    #[test]
403	    fn mth_rfc6962() {
404	        // Empty tree: SHA-256 of empty input.
405	        assert_eq!(hex_of(&mth(&[])), hex_of(&sha256(b"")));
406	        // Single leaf: SHA-256(0x00 || leaf).
407	        let leaf = b"hello";
408	        let mut expect = vec![0x00];
409	        expect.extend_from_slice(leaf);
410	        assert_eq!(hex_of(&mth(&[leaf])), hex_of(&sha256(&expect)));
411	        // Two leaves: SHA-256(0x01 || L || R).
412	        let l = mth(&[b"a"]);
413	        let r = mth(&[b"b"]);
414	        let mut expect = vec![0x01];
415	        expect.extend_from_slice(&l);
416	        expect.extend_from_slice(&r);
417	        assert_eq!(hex_of(&mth(&[b"a", b"b"])), hex_of(&sha256(&expect)));
418	        // Three leaves: split k=2, right subtree is a single leaf.
419	        let left = mth(&[b"a", b"b"]);
420	        let right = mth(&[b"c"]);
421	        let mut expect = vec![0x01];
422	        expect.extend_from_slice(&left);
423	        expect.extend_from_slice(&right);
424	        assert_eq!(hex_of(&mth(&[b"a", b"b", b"c"])), hex_of(&sha256(&expect)));
425	    }
