427	    #[test]
428	    fn audit_paths_verify_at_every_position_for_many_sizes() {
429	        // Sizes both sides of several power-of-two boundaries (uneven sizes
430	        // must not pad with empty or duplicated trailing records).
431	        let sizes: Vec<usize> = (1..=18).chain([31, 32, 33, 63, 64, 65, 100, 127, 128, 129, 257]).collect();
432	        for n in sizes {
433	            let records: Vec<Vec<u8>> = (0..n).map(|i| format!("record-{i:04}").into_bytes()).collect();
434	            let refs: Vec<&[u8]> = records.iter().map(|r| r.as_slice()).collect();
435	            let root = mth(&refs);
436	            for m in 0..n {
437	                let path = inclusion_path(&refs, m);
438	                if n == 1 {
439	                    assert!(path.is_empty(), "single record must have an empty path");
440	                } else {
441	                    // Path length is bounded by the tree depth; for an even
442	                    // power-of-two batch every position sits at full depth.
443	                    let depth = usize::BITS - (n - 1).leading_zeros();
444	                    if n.is_power_of_two() {
445	                        assert_eq!(path.len(), depth as usize, "n={n}, m={m}");
446	                    } else {
447	                        assert!(path.len() <= depth as usize, "n={n}, m={m}");
448	                    }
449	                }
450	                let computed = verify_proof(refs[m], m, n, &path);
451	                assert_eq!(hex_of(&computed), hex_of(&root), "proof mismatch at n={n}, m={m}");
452	            }
453	        }
454	    }
