471	    #[test]
472	    fn duplicate_content_gets_distinct_position_specific_proofs() {
473	        // Same bytes at positions 0 and 4 (like the regression batch): the
474	        // proofs must anchor the exact requested position.
475	        let refs: Vec<&[u8]> = vec![b"x", b"a", b"b", b"c", b"x", b"d", b"e"];
476	        let n = refs.len();
477	        let root = mth(&refs);
478	        let p0 = inclusion_path(&refs, 0);
479	        let p4 = inclusion_path(&refs, 4);
480	        assert_ne!(p0, p4, "equal content at different positions needs different proofs");
481	        assert_eq!(hex_of(&verify_proof(b"x", 0, n, &p0)), hex_of(&root));
482	        assert_eq!(hex_of(&verify_proof(b"x", 4, n, &p4)), hex_of(&root));
483	        // The proof for position 4 must not verify at position 0.
484	        let wrong = verify_proof(b"x", 0, n, &p4);
485	        assert_ne!(hex_of(&wrong), hex_of(&root));
486	    }
