488	    #[test]
489	    fn proof_for_uneven_batch_does_not_use_padded_tree() {
490	        // n=5: RFC split k=4, so leaf 4 pairs directly with MTH of the whole
491	        // size-4 subtree — a single sibling. A power-of-two padding scheme
492	        // would pad to 8 and emit a three-element path instead.
493	        let owned: Vec<Vec<u8>> = (0..5).map(|i| vec![b'a' + i as u8]).collect();
494	        let refs: Vec<&[u8]> = owned.iter().map(|v| v.as_slice()).collect();
