fn root_and_path_rec(leaves: &[&[u8]], m: usize, path: &mut Vec<[u8; 32]>) -> [u8; 32] {
    let n = leaves.len();
    if n == 1 {
        let mut input = Vec::with_capacity(1 + leaves[0].len());
        input.push(0x00);
        input.extend_from_slice(leaves[0]);
        return sha256(&input);
